declare
 m jsonb := $manifest${"batch":"sail-result-2025-2026-10-28","event":{"id":"902a5f6d-c9fd-5f62-8dd7-aafbe28e045b","slug":"trat-regatta-2025","name":"Trat Regatta 2025","startDate":"2025-05-09","endDate":"2025-05-11","venue":"Laem Sok, Trat, Thailand","organizer":"Yacht Racing Association of Thailand","classes":["ILCA 4","ILCA 6","ILCA 7","Optimist"]},"sheet":{"id":"b8df6f6f-d18a-52db-a03b-7b0e96603c00","slug":"trat-regatta-2025-ilca6","name":"Trat Regatta 2025 — ILCA 6","boatClass":"ILCA 6","division":"Open","raceCount":3,"totalFleetSize":9,"entryType":"individual","minParticipants":1,"maxParticipants":1},"officialSource":{"url":"https://www.racingrulesofsailing.org/documents/141364","title":"Trat Regatta 2025 — ILCA 6 Open results","type":"pdf","provisional":false,"publicationStatus":"final","visuallyReviewed":true,"pdfSearch":null},"results":[{"eventKey":"trat-regatta-2025","sourceDocument":141364,"sourcePage":1,"sourceClass":"ILCA 6","boatClass":"ILCA 6","division":"Open","rank":1,"name":"THANAPAT SIRICHAROEN","sailOrBoardNumber":"THA210250","club":"YRAT","nationality":null,"gender":"M","officialBirthYear":2006,"sourceBirthYear":"2006","grossScore":4.0,"nettScore":4.0,"races":[{"raceNumber":1,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":2,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":3,"score":2.0,"code":null,"discarded":false,"raw":"2.0"}],"handicap":false,"sailorId":"de0550e0-b07f-5842-b791-00b8a2d9d4a1","identityBasis":"Unique exact normalized full name or previously reviewed source alias; existing metadata unchanged.","resultId":"cc397a47-9dcc-56b8-bfd2-acc406e2b8a5","participants":[{"id":"3382bc9c-7756-5c1a-b3bf-d00e4621bbb8","sailorId":"de0550e0-b07f-5842-b791-00b8a2d9d4a1","sourceName":"THANAPAT SIRICHAROEN","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 6; page 1; source name: THANAPAT SIRICHAROEN; historic sail: THA210250; club: YRAT; year field: 2006. Unique exact normalized f